	ep, err := s.db.Client.Project.Query().
		Where(
			project.ID(projectID),
			project.HasMembersWith(projectmember.UserID(userID)),
		).
		Only(ctx)
	if err != nil {
		if ent.IsNotFound(err) {
			respondError(w, http.StatusNotFound, "project not found", "not_found")
			return
		}
