const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
  const file = e.target.files?.[0]
  if (!file) return

  const allowedTypes = ['image/', 'video/', 'application/pdf']
  if (!allowedTypes.some(t => file.type.startsWith(t))) {
